node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get deal D006 details
console.log('=== DEAL D006 ===');
console.log('Deal ID: D006');
console.log('Rep: James Okafor');
console.log('Region: South');
console.log('Product: Meridian Insights Pro');
console.log('Amount: \$120,000');
console.log('Close Date: 2026-07-22');
console.log('Status: won');

// Get all flights with full date info
console.log('\n=== ALL FLIGHTS (tau2Airline) ===');
const flights = db.prepare(\"SELECT * FROM flights WHERE source_skill='tau2Airline'\").all();

// Build flight route map for one-stop analysis
const routeMap = {};  // origin -> [{flight_id, destination, dep, arr, dates_json}]
flights.forEach(f => {
  const dates = JSON.parse(f.dates_json || '{}');
  if (!routeMap[f.origin]) routeMap[f.origin] = [];
  routeMap[f.origin].push({
    flight_id: f.flight_id,
    origin: f.origin,
    destination: f.destination,
    dep: f.departure_time,
    arr: f.arrival_time,
    dates: dates
  });
});

// Find all possible one-stop routes
console.log('\n=== ALL POSSIBLE ONE-STOP ROUTES ===');
const origins = Object.keys(routeMap);
for (const o of origins) {
  for (const leg1 of routeMap[o]) {
    if (routeMap[leg1.destination]) {
      for (const leg2 of routeMap[leg1.destination]) {
        if (leg2.destination !== o) {  // not going back to origin
          // Check if arrival of leg1 <= departure of leg2
          if (leg1.arr && leg2.dep && leg1.arr <= leg2.dep) {
            // Check for available dates overlap
            const l1dates = Object.keys(leg1.dates);
            const l2dates = Object.keys(leg2.dates);
            const commonDates = l1dates.filter(d => l2dates.includes(d));
            const availDates = commonDates.filter(d => 
              leg1.dates[d].status === 'available' && leg2.dates[d].status === 'available'
            );
            if (availDates.length > 0) {
              console.log(o, '->', leg1.destination, '->', leg2.destination);
              console.log('  Leg 1:', leg1.flight_id, 'dep:', leg1.dep, 'arr:', leg1.arr);
              console.log('  Leg 2:', leg2.flight_id, 'dep:', leg2.dep, 'arr:', leg2.arr);
              console.log('  Available dates:', availDates.join(', '));
              // Print prices for first available date
              const d = availDates[0];
              console.log('  Leg 1 prices:', JSON.stringify(leg1.dates[d].prices));
              console.log('  Leg 2 prices:', JSON.stringify(leg2.dates[d].prices));
              console.log('  Leg 1 seats:', JSON.stringify(leg1.dates[d].available_seats));
              console.log('  Leg 2 seats:', JSON.stringify(leg2.dates[d].available_seats));
              console.log();
            }
          }
        }
      }
    }
  }
}
"

