node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get all tau2Airline users
const users = db.prepare(\"SELECT user_id, name, email, loyalty_tier FROM users WHERE skill_ids_json LIKE '%tau2Airline%'\").all();
console.log('=== tau2Airline Users ===');
users.forEach(u => console.log(u.user_id, '|', u.name, '|', u.email, '|', u.loyalty_tier));

// Also let's get unique one-stop route summaries (distinct origin->layover->destination pairs)
console.log('\n=== Unique One-Stop Routes ===');
const flights = db.prepare(\"SELECT * FROM flights WHERE source_skill='tau2Airline'\").all();
const routeMap = {};
flights.forEach(f => {
  const dates = JSON.parse(f.dates_json || '{}');
  const hasAvailable = Object.values(dates).some(d => d.status === 'available');
  if (!hasAvailable) return;
  if (!routeMap[f.origin]) routeMap[f.origin] = [];
  routeMap[f.origin].push({
    flight_id: f.flight_id, origin: f.origin, destination: f.destination,
    dep: f.departure_time, arr: f.arrival_time, dates
  });
});

const routes = new Set();
for (const o of Object.keys(routeMap)) {
  for (const leg1 of routeMap[o]) {
    if (routeMap[leg1.destination]) {
      for (const leg2 of routeMap[leg1.destination]) {
        if (leg2.destination !== o && leg1.arr && leg2.dep && leg1.arr <= leg2.dep) {
          routes.add(o + ' -> ' + leg1.destination + ' -> ' + leg2.destination);
        }
      }
    }
  }
}
routes.forEach(r => console.log(r));
"
